using System.Security;using System.Text;using Npgsql;
namespace IcpaaS.Api;
public static class ProvisioningEndpoints{public static void MapProvisioning(this WebApplication app){app.MapPost("/internal/freeswitch/xml",async(HttpRequest req,PlatformStore store,IConfiguration cfg,CancellationToken ct)=>{if(!Valid(req,cfg))return Results.Unauthorized();var form=await req.ReadFormAsync(ct);var section=form["section"].ToString();var key=form["key_value"].ToString();if(section=="dialplan")return Results.Text(await Dialplan(store,key,ct),"application/xml");if(section=="directory")return Results.Text(await Directory(store,key,ct),"application/xml");return Results.Text("<document type=\"freeswitch/xml\"><section name=\"result\"><result status=\"not found\"/></section></document>","application/xml");});app.MapGet("/internal/asterisk/{nodeKey}/pjsip",async(string nodeKey,HttpRequest req,PlatformStore store,IConfiguration cfg,CancellationToken ct)=>{if(!Valid(req,cfg))return Results.Unauthorized();await using var c=await store.Open(ct);await using var q=new NpgsqlCommand("SELECT t.trunk_key,t.remote_endpoint,t.authentication_mode,t.username,t.secret_ref,t.transport,t.codecs,t.default_cli FROM trunks t JOIN telephony_nodes n ON n.id=t.node_id WHERE n.node_key=$1 AND t.enabled ORDER BY t.priority",c);q.Parameters.AddWithValue(nodeKey);await using var r=await q.ExecuteReaderAsync(ct);var trunks=new List<object>();while(await r.ReadAsync(ct))trunks.Add(new{trunkKey=r.GetString(0),remoteEndpoint=r.GetString(1),authenticationMode=r.GetString(2),username=r.IsDBNull(3)?null:r.GetString(3),secretRef=r.IsDBNull(4)?null:r.GetString(4),transport=r.GetString(5),codecs=(string[])r[6],defaultCli=r.IsDBNull(7)?null:r.GetString(7)});return Results.Ok(new{revision=DateTimeOffset.UtcNow.ToUnixTimeSeconds(),trunks});});}
static bool Valid(HttpRequest r,IConfiguration c){var expected=c["ICPaaS:Security:NodeKey"]??"";return expected.Length>=24&&r.Headers["X-ICPaaS-Node-Key"]==expected;}static string X(string v)=>SecurityElement.Escape(v)??"";
static async Task<string> Dialplan(PlatformStore store,string did,CancellationToken ct){await using var c=await store.Open(ct);await using var q=new NpgsqlCommand("SELECT d.number_e164 FROM dids d JOIN routes r ON r.did_id=d.id JOIN processes p ON p.id=r.process_id WHERE d.number_e164=$1 AND d.enabled AND r.enabled AND p.enabled AND p.process_type IN('inbound','blended') ORDER BY r.priority LIMIT 1",c);q.Parameters.AddWithValue(did);var found=await q.ExecuteScalarAsync(ct);if(found is null)return "<document type=\"freeswitch/xml\"><section name=\"result\"><result status=\"not found\"/></section></document>";return $"<document type=\"freeswitch/xml\"><section name=\"dialplan\"><context name=\"public\"><extension name=\"icpaas-{X(did)}\"><condition field=\"destination_number\" expression=\"^{X(did)}$\"><action application=\"set\" data=\"icpaas_managed=true\"/><action application=\"set\" data=\"icpaas_call_id=${{uuid}}\"/><action application=\"set\" data=\"icpaas_inbound_did={X(did)}\"/><action application=\"park\"/></condition></extension></context></section></document>";}
static async Task<string> Directory(PlatformStore store,string extension,CancellationToken ct){await using var c=await store.Open(ct);await using var q=new NpgsqlCommand("SELECT extension,sip_ha1 FROM agent_endpoints WHERE extension=$1",c);q.Parameters.AddWithValue(extension);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return "<document type=\"freeswitch/xml\"><section name=\"result\"><result status=\"not found\"/></section></document>";return $"<document type=\"freeswitch/xml\"><section name=\"directory\"><domain name=\"$${{domain}}\"><user id=\"{X(extension)}\"><params><param name=\"a1-hash\" value=\"{X(r.GetString(1))}\"/></params></user></domain></section></document>";}}
